// One item: weight 2, value 3, capacity 4
//
// 0/1 (descending: w = 4, 3, 2):
//   w = 4: dp[4] = max(0, dp[2] + 3) = 3     dp[2] has not been updated yet, so it is still 0
//   w = 3: dp[3] = max(0, dp[1] + 3) = 3
//   w = 2: dp[2] = max(0, dp[0] + 3) = 3
//   result: dp[4] = 3, the item is used once
//
// Unbounded (ascending: w = 2, 3, 4):
//   w = 2: dp[2] = max(0, dp[0] + 3) = 3
//   w = 3: dp[3] = max(0, dp[1] + 3) = 3
//   w = 4: dp[4] = max(0, dp[2] + 3) = 6     dp[2] already includes the item
//   result: dp[4] = 6, the item is used twice

fun knapsack2D(weights: IntArray, values: IntArray, capacity: Int): Int {
    val n = weights.size
    // dp[i][w] = best value using the first i items with capacity w
    val dp = Array(n + 1) { IntArray(capacity + 1) }
    for (i in 1..n) {
        val wt = weights[i - 1]
        val value = values[i - 1]
        for (w in 0..capacity) {
            dp[i][w] = dp[i - 1][w]                                   // skip item i
            if (wt <= w) {
                dp[i][w] = maxOf(dp[i][w], dp[i - 1][w - wt] + value) // take item i
            }
        }
    }
    return dp[n][capacity]
}
// Time: O(n * W)   Space: O(n * W)

fun knapsack1D(weights: IntArray, values: IntArray, capacity: Int): Int {
    val dp = IntArray(capacity + 1)                  // dp[w] = best value with capacity w
    for (i in weights.indices) {
        for (w in capacity downTo weights[i]) {      // DOWNWARD so each item is used at most once
            dp[w] = maxOf(dp[w], dp[w - weights[i]] + values[i])
        }
    }
    return dp[capacity]
}
// Time: O(n * W)   Space: O(W)

fun unboundedKnapsack(weights: IntArray, values: IntArray, capacity: Int): Int {
    val dp = IntArray(capacity + 1)
    for (i in weights.indices) {
        for (w in weights[i]..capacity) {            // UPWARD so the item can be reused
            dp[w] = maxOf(dp[w], dp[w - weights[i]] + values[i])
        }
    }
    return dp[capacity]
}
// Time: O(n * W)   Space: O(W)

fun canMakeSum(nums: IntArray, target: Int): Boolean {
    val dp = BooleanArray(target + 1)
    dp[0] = true                                     // the empty subset makes 0
    for (x in nums) {
        for (s in target downTo x) {
            if (dp[s - x]) dp[s] = true              // reach s by adding x to a reachable s - x
        }
    }
    return dp[target]
}
// Time: O(n * target)   Space: O(target)

fun countSubsets(nums: IntArray, target: Int): Int {
    val dp = IntArray(target + 1)
    dp[0] = 1                                        // one way to make 0: take nothing
    for (x in nums) {
        for (s in target downTo x) {
            dp[s] += dp[s - x]                       // ways without x are already in dp[s]
        }
    }
    return dp[target]
}
// Time: O(n * target)   Space: O(target)

fun knapsackMemo(weights: IntArray, values: IntArray, capacity: Int): Int {
    val n = weights.size
    val memo = Array(n) { IntArray(capacity + 1) { -1 } }

    fun solve(i: Int, cap: Int): Int {
        if (i == n) return 0
        if (memo[i][cap] != -1) return memo[i][cap]
        var best = solve(i + 1, cap)                                     // skip item i
        if (weights[i] <= cap) {
            best = maxOf(best, values[i] + solve(i + 1, cap - weights[i]))   // take item i
        }
        memo[i][cap] = best
        return best
    }

    return solve(0, capacity)
}
// Time: O(n * W)   Space: O(n * W) plus recursion

fun knapsackItems(weights: IntArray, values: IntArray, capacity: Int): List<Int> {
    val n = weights.size
    val dp = Array(n + 1) { IntArray(capacity + 1) }
    for (i in 1..n) {
        for (w in 0..capacity) {
            dp[i][w] = dp[i - 1][w]
            if (weights[i - 1] <= w) {
                dp[i][w] = maxOf(dp[i][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            }
        }
    }

    val chosen = mutableListOf<Int>()
    var w = capacity
    for (i in n downTo 1) {
        if (dp[i][w] != dp[i - 1][w]) {              // the value changed, so item i - 1 was taken
            chosen.add(i - 1)
            w -= weights[i - 1]
        }
    }
    chosen.reverse()
    return chosen
}
// Time: O(n * W)   Space: O(n * W), the full table is needed for reconstruction

fun boundedKnapsack(weights: IntArray, values: IntArray, counts: IntArray, capacity: Int): Int {
    val dp = IntArray(capacity + 1)
    for (i in weights.indices) {
        var remaining = counts[i]
        var chunk = 1
        while (remaining > 0) {                      // chunks of 1, 2, 4, ... plus a remainder
            val take = minOf(chunk, remaining)
            val w = weights[i] * take
            val v = values[i] * take
            for (c in capacity downTo w) {           // each chunk acts like one 0/1 item
                dp[c] = maxOf(dp[c], dp[c - w] + v)
            }
            remaining -= take
            chunk *= 2
        }
    }
    return dp[capacity]
}
// Time: O(W * sum of log(counts[i]))   Space: O(W)

fun main() {
    val weights = intArrayOf(1, 3, 4, 5)
    val values = intArrayOf(1, 4, 5, 7)
    println(knapsack1D(weights, values, 7))          // 9: take weights 3 and 4 (values 4 + 5)
}
