fun canPartition(nums: IntArray): Boolean {
    val total = nums.sum()
    if (total % 2 != 0) return false                 // an odd total cannot split evenly
    val target = total / 2
    val dp = BooleanArray(target + 1)
    dp[0] = true
    for (x in nums) {
        for (s in target downTo x) {
            if (dp[s - x]) dp[s] = true
        }
        if (dp[target]) return true                  // early exit
    }
    return dp[target]
}
// Time: O(n * total / 2)   Space: O(total / 2)

import kotlin.math.abs

fun findTargetSumWays(nums: IntArray, target: Int): Int {
    val total = nums.sum()
    // P - N = target and P + N = total, so P = (target + total) / 2
    if (abs(target) > total || (target + total) % 2 != 0) return 0
    val subsetSum = (target + total) / 2
    val dp = IntArray(subsetSum + 1)
    dp[0] = 1
    for (x in nums) {
        for (s in subsetSum downTo x) {
            dp[s] += dp[s - x]
        }
    }
    return dp[subsetSum]
}
// Time: O(n * subsetSum)   Space: O(subsetSum)
// Zeros are handled correctly: each zero doubles the count

fun countSubsetsWithDiff(nums: IntArray, diff: Int): Int {
    val total = nums.sum()
    if (total < diff || (total + diff) % 2 != 0) return 0
    return countSubsets(nums, (total + diff) / 2)     // subset sum S1 = (total + diff) / 2
}
// Time: O(n * total)   Space: O(total)

fun lastStoneWeightII(stones: IntArray): Int {
    val total = stones.sum()
    val half = total / 2
    val dp = BooleanArray(half + 1)
    dp[0] = true
    for (x in stones) {
        for (s in half downTo x) {
            if (dp[s - x]) dp[s] = true
        }
    }
    for (s in half downTo 0) {
        if (dp[s]) return total - 2 * s              // the best group sum closest to half
    }
    return total
}
// Time: O(n * total / 2)   Space: O(total / 2)

fun findMaxForm(strs: Array<String>, m: Int, n: Int): Int {
    // dp[i][j] = most strings we can pick using at most i zeros and j ones
    val dp = Array(m + 1) { IntArray(n + 1) }
    for (s in strs) {
        val zeros = s.count { it == '0' }
        val ones = s.length - zeros
        for (i in m downTo zeros) {                  // both loops descend: each string used once
            for (j in n downTo ones) {
                dp[i][j] = maxOf(dp[i][j], dp[i - zeros][j - ones] + 1)
            }
        }
    }
    return dp[m][n]
}
// Time: O(len * m * n)   Space: O(m * n)

fun coinChange(coins: IntArray, amount: Int): Int {
    val inf = amount + 1
    val dp = IntArray(amount + 1) { inf }
    dp[0] = 0
    for (c in coins) {
        for (a in c..amount) {                       // ascending: each coin can be reused
            if (dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1
        }
    }
    return if (dp[amount] >= inf) -1 else dp[amount]
}
// Time: O(amount * coins)   Space: O(amount)

fun change(amount: Int, coins: IntArray): Int {
    val dp = IntArray(amount + 1)
    dp[0] = 1
    for (c in coins) {                               // coins OUTER counts combinations
        for (a in c..amount) {
            dp[a] += dp[a - c]
        }
    }
    return dp[amount]
}
// Time: O(amount * coins)   Space: O(amount)
// Putting amounts in the outer loop would count permutations (Combination Sum IV)

fun rodCutting(prices: IntArray, n: Int): Int {
    // prices[i] is the price of a piece of length i + 1
    val dp = IntArray(n + 1)
    for (len in 1..n) {
        for (cut in 1..minOf(len, prices.size)) {
            dp[len] = maxOf(dp[len], dp[len - cut] + prices[cut - 1])
        }
    }
    return dp[n]
}
// Time: O(n²)   Space: O(n)

fun numRollsToTarget(n: Int, k: Int, target: Int): Int {
    val mod = 1_000_000_007
    var dp = IntArray(target + 1)
    dp[0] = 1                                        // zero dice make sum zero
    repeat(n) {                                      // one layer per die
        val next = IntArray(target + 1)
        for (s in 1..target) {
            for (face in 1..minOf(k, s)) {
                next[s] = (next[s] + dp[s - face]) % mod
            }
        }
        dp = next                                    // the previous layer stays read-only while building the next
    }
    return dp[target]
}
// Time: O(n * target * k)   Space: O(target)

fun minSubsetSumDifference(nums: IntArray): Int {
    val total = nums.sum()
    val half = total / 2
    val dp = BooleanArray(half + 1)
    dp[0] = true
    for (x in nums) {
        for (s in half downTo x) {
            if (dp[s - x]) dp[s] = true
        }
    }
    var best = 0
    for (s in 0..half) if (dp[s]) best = s           // the largest reachable sum not exceeding half
    return total - 2 * best
}
// Time: O(n * total / 2)   Space: O(total / 2)

fun numSquares(n: Int): Int {
    val dp = IntArray(n + 1) { Int.MAX_VALUE }
    dp[0] = 0
    var j = 1
    while (j * j <= n) {
        val sq = j * j
        for (a in sq..n) {                           // unbounded: a square can be reused
            if (dp[a - sq] != Int.MAX_VALUE && dp[a - sq] + 1 < dp[a]) dp[a] = dp[a - sq] + 1
        }
        j++
    }
    return dp[n]
}
// Time: O(n * sqrt(n))   Space: O(n)
